/* Simple lit material (tether, latex knot) */
function makeSimpleLitMat(color, gloss, spec, rim, trans, alpha) {
  return new THREE.ShaderMaterial({
    uniforms: Object.assign({
      uColor: { value: new THREE.Color(color[0], color[1], color[2]) },
      uGloss: { value: gloss }, uSpec: { value: spec }, uRim: { value: rim },
      uTrans: { value: trans }, uAlpha: { value: alpha }
    }, lightUniforms),
    vertexShader: `
      varying vec3 vN; varying vec3 vW;
      void main(){
        vN = normalize(mat3(modelMatrix) * normal);
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vW = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: LIGHT_DECLS + '\n' + LIGHT_FUNCS + `
      uniform vec3 uColor; uniform float uGloss; uniform float uSpec;
      uniform float uRim; uniform float uTrans; uniform float uAlpha;
      varying vec3 vN; varying vec3 vW;
      void main(){
        vec3 N = normalize(vN);
        vec3 V = normalize(cameraPosition - vW);
        if (!gl_FrontFacing) N = -N;
        vec3 col = studioShade(N, V, vW, uColor, uGloss, uSpec, uRim, uTrans, uColor * 1.6);
        gl_FragColor = vec4(col, uAlpha);
      }`
  });
}

/* Copper/brass bullet */
const bulletMat = new THREE.ShaderMaterial({
  uniforms: Object.assign({}, lightUniforms),
  vertexShader: `
    varying vec2 vUv; varying vec3 vN; varying vec3 vW;
    void main(){
      vUv = uv;
      vN = normalize(mat3(modelMatrix) * normal);
      vec4 wp = modelMatrix * vec4(position, 1.0);
      vW = wp.xyz;
      gl_Position = projectionMatrix * viewMatrix * wp;
    }`,
  fragmentShader: LIGHT_DECLS + '\n' + LIGHT_FUNCS + `
    varying vec2 vUv; varying vec3 vN; varying vec3 vW;
    void main(){
      vec3 N = normalize(vN);
      vec3 V = normalize(cameraPosition - vW);
      if (!gl_FrontFacing) N = -N;
      float v = vUv.y;
      vec3 base = mix(vec3(0.55, 0.30, 0.13), vec3(0.72, 0.52, 0.20), smoothstep(0.52, 0.72, v));
      float band = smoothstep(0.24, 0.265, v) * (1.0 - smoothstep(0.31, 0.335, v));  // cannelure
      base *= 1.0 - 0.55 * band;
      base *= 0.85 + 0.3 * smoothstep(0.0, 0.1, v);                                  // boattail
      float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
      vec3 col = studioShade(N, V, vW, base, 240.0, 1.60, 0.90, 0.0, vec3(0.0));
      col += vec3(0.10, 0.13, 0.18) * fres;
      gl_FragColor = vec4(col, 1.0);
    }`
});

/* Water chunk blobs (merged icospheres, transformed on CPU each frame) */
const chunkMat = new THREE.ShaderMaterial({
  uniforms: Object.assign({}, lightUniforms),
  vertexShader: `
    attribute float aFade;
    attribute vec3 aColor;
    varying vec3 vN; varying vec3 vW; varying vec3 vC; varying float vFade;
    void main(){
      vN = normalize(mat3(modelMatrix) * normal);
      vec4 wp = modelMatrix * vec4(position, 1.0);
      vW = wp.xyz; vC = aColor; vFade = aFade;
      gl_Position = projectionMatrix * viewMatrix * wp;
    }`,
  fragmentShader: LIGHT_DECLS + '\n' + LIGHT_FUNCS + `
    varying vec3 vN; varying vec3 vW; varying vec3 vC; varying float vFade;
    void main(){
      if (vFade <= 0.004) discard;
      vec3 N = normalize(vN);
      vec3 V = normalize(cameraPosition - vW);
      if (!gl_FrontFacing) N = -N;
      float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
      vec3 col = studioShade(N, V, vW, vC, 170.0, 1.15, 1.65, 0.35, vec3(0.75, 0.88, 1.0));
      col += vec3(0.85, 0.94, 1.0) * fres * 0.5;
      float alpha = clamp(0.86 + fres * 0.12, 0.0, 1.0) * vFade;
      if (alpha <= 0.004) discard;
      gl_FragColor = vec4(col, alpha);
    }`,
  transparent: true, depthWrite: true
});

/* Additive vapor glow inside the cavitation tunnel */
const tunnelMat = new THREE.ShaderMaterial({
  uniforms: { uAmt: { value: 0 } },
  vertexShader: `
    varying vec2 vUv;
    void main(){
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: `
    uniform float uAmt;
    varying vec2 vUv;
    void main(){
      float ends = smoothstep(0.0, 0.18, vUv.y) * (1.0 - smoothstep(0.82, 1.0, vUv.y));
      float a = uAmt * ends * 0.32;
      gl_FragColor = vec4(vec3(0.62, 0.80, 1.0) * a, a);
    }`,
  transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide
});

/* Point sprites (droplets + mist) */
const PTS_VERT = `
attribute float aSize;
attribute float aAlpha;
attribute vec3 aColor;
varying float vAlpha; varying vec3 vColor;
uniform float uPixelScale;
void main(){
  vColor = aColor;
  vAlpha = aAlpha;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  float ps = aSize * uPixelScale / max(0.25, -mv.z);
  gl_PointSize = clamp(ps, 1.0, 130.0);
  gl_Position = projectionMatrix * mv;
}`;
const PTS_FRAG = `
uniform sampler2D uMap;
varying float vAlpha; varying vec3 vColor;
void main(){
  if (vAlpha <= 0.004) discard;
  vec4 tx = texture2D(uMap, gl_PointCoord);
  float a = tx.a * vAlpha;
  if (a <= 0.004) discard;
  gl_FragColor = vec4(vColor * tx.rgb, a);
}`;
function makePointsMaterial(blending) {
  return new THREE.ShaderMaterial({
    uniforms: { uMap: { value: spriteTex }, uPixelScale: { value: 300 } },
    vertexShader: PTS_VERT, fragmentShader: PTS_FRAG,
    transparent: true, depthWrite: false, depthTest: true, blending: blending
  });
}

