/* ---------------- Pure phase functions of simTime ---------------- */
function bulletX(t) {
  if (t < 1.0) return 7.5 + (IMPACT_X - 7.5) * t;                 // approach from off-screen right
  if (t < 3.8) {                                                   // decelerating traverse through water
    const tau = (t - 1.0) / 2.8, a = 1.5, nrm = 1 - Math.exp(-a);
    return IMPACT_X - 2.04 * (1 - Math.exp(-a * tau)) / nrm;
  }
  return -IMPACT_X - 0.879 * (1 - Math.exp(-0.22 * (t - 3.8))) / 0.22;  // post-exit flight
}
function bulletState(t) {
  const x = bulletX(t);
  let y = IMPACT_Y, tumble = 0;
  if (t >= 1.35) tumble = 0.5 * (t - 1.35);
  if (t >= 3.8) {
    y = IMPACT_Y - 0.15 * (t - 3.8) * (t - 3.8);
    tumble = 1.225 + 0.45 * (t - 3.8);
  }
  return { x: x, y: y, tumble: tumble };
}
function swingAngle(t) {
  let a = 0.02 * Math.sin(2 * Math.PI * 0.35 * t);                 // gentle pre-impact sway
  if (t > 1.0) { const u = t - 1.0; a -= 0.055 * Math.exp(-1.15 * u) * Math.sin(2 * Math.PI * 1.05 * u); }
  if (t > 3.8) { const u = t - 3.8; a -= 0.014 * Math.exp(-1.0 * u) * Math.sin(2 * Math.PI * 1.2 * u); }
  return a;
}
const LP = { dimple: 0, tearR: 0, contract: 0, alpha: 1 };
function latexPhases(t) {
  LP.dimple = t < 1.0 ? 0
    : (t < 1.14 ? 0.5 * (1 - Math.cos(Math.PI * (t - 1.0) / 0.14))
      : Math.max(0, 1 - (t - 1.14) / 0.18));
  const u = clamp01((t - 1.10) / 0.45);
  LP.tearR = t < 1.10 ? 0 : 2.85 * (1 - Math.pow(1 - u, 1.5));     // tear front: ~4-5x fluid speed
  let c = smooth01((t - 1.10) / 0.48);
  if (t > 1.58) { const u2 = t - 1.58; c = 1 + 0.20 * Math.exp(-5.5 * u2) * Math.sin(22 * u2); }
  LP.contract = c;
  LP.alpha = 1 - smooth(1.34, 1.62, t);
  return LP;
}
const WP = { redTint: 1, wobbleAmp: 0, tunnelR: 0, tunnelAmt: 0, sagY: 0, stretchY: 1, stretchXZ: 1, pinch: 0, erode: 0, bulletX: 8 };
function waterPhases(t) {
  WP.redTint = 1 - smooth(1.05, 2.0, t);
  WP.wobbleAmp = 0.045 * (smooth(1.5, 1.72, t) * (1 - smooth(2.3, 3.4, t)))
               + 0.020 * (smooth(2.35, 2.5, t) * (1 - smooth(3.1, 4.0, t)));
  let tr = 0;
  if (t >= 2.35) {
    tr = lerp(0.10, 0.46, smooth(2.35, 3.8, t));
    if (t > 3.8) {
      const u = t - 3.8;
      tr = lerp(0.46, 0.30, smooth(3.8, 4.8, t)) + 0.03 * Math.exp(-1.1 * u) * Math.sin(13 * u);
    }
  }
  WP.tunnelR = tr;
  WP.tunnelAmt = smooth(2.35, 2.62, t) * (1 - smooth(4.6, 5.2, t));
  const sag1 = t > 2.4 ? 0.03 * (t - 2.4) * (t - 2.4) : 0;
  const sag2 = t > 5.0 ? 0.17 * (t - 5.0) * (t - 5.0) : 0;
  WP.sagY = Math.min(sag1 + sag2, 2.9);
  WP.stretchY = 1 + 0.24 * smooth(4.8, 6.8, t);
  WP.stretchXZ = 1 - 0.16 * smooth(4.8, 6.8, t);
  WP.pinch = 0.72 * smooth(4.5, 6.2, t);
  WP.erode = smooth(4.9, 7.25, t);
  WP.bulletX = bulletX(t);
  return WP;
}
function mirrorBody(x, y, z, t) {   // JS mirror of the water vertex transform (for spawn sampling)
  waterPhases(t);
  const topMask = smooth(IMPACT_Y + 0.25, IMPACT_Y + 1.45, y);
  const pinchS = 1 - WP.pinch * topMask;
  return [
    x * pinchS * WP.stretchXZ,
    IMPACT_Y + (y - IMPACT_Y) * WP.stretchY + WP.sagY,
    z * pinchS * WP.stretchXZ
  ];
}
const sagAt = (tt) => tt > 2.4 ? 0.03 * (tt - 2.4) * (tt - 2.4) : 0;

