function buildSystem(sysVal, blending, renderOrder) {
  const recs = ALL.filter(r => r.sys === sysVal);
  const g = new THREE.BufferGeometry();
  const pos = new Float32Array(recs.length * 3);
  const col = new Float32Array(recs.length * 3);
  const sz = new Float32Array(recs.length);
  const al = new Float32Array(recs.length);
  for (let i = 0; i < recs.length; i++) {
    col[i * 3] = recs[i].cr; col[i * 3 + 1] = recs[i].cg; col[i * 3 + 2] = recs[i].cb;
  }
  const posAttr = new THREE.BufferAttribute(pos, 3); posAttr.setUsage(THREE.DynamicDrawUsage);
  const sizeAttr = new THREE.BufferAttribute(sz, 1); sizeAttr.setUsage(THREE.DynamicDrawUsage);
  const alphaAttr = new THREE.BufferAttribute(al, 1); alphaAttr.setUsage(THREE.DynamicDrawUsage);
  g.setAttribute('position', posAttr);
  g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
  g.setAttribute('aSize', sizeAttr);
  g.setAttribute('aAlpha', alphaAttr);
  const mat = makePointsMaterial(blending);
  const points = new THREE.Points(g, mat);
  points.frustumCulled = false;
  points.renderOrder = renderOrder;
  scene.add(points);
  return { recs: recs, posAttr: posAttr, sizeAttr: sizeAttr, alphaAttr: alphaAttr, mat: mat };
}
const dropSys = buildSystem(0, THREE.NormalBlending, 6);
const mistSys = buildSystem(1, THREE.AdditiveBlending, 5);

function updatePoints(sys, t) {
  const recs = sys.recs;
  const pos = sys.posAttr.array, szA = sys.sizeAttr.array, alA = sys.alphaAttr.array;
  for (let i = 0; i < recs.length; i++) {
    const r = recs[i];
    const tau = t - r.t0;
    let a = 0, s = 0, x = r.x, y = r.y, z = r.z;
    if (tau >= 0 && tau <= r.life) {
      if (r.mode === 0) {
        x = r.x + r.vx * tau;
        y = r.y + r.vy * tau - 0.5 * r.gy * tau * tau;
        z = r.z + r.vz * tau;
      } else {
