    state = 'PLAYING';
    setToggleIcon('pause');
  } else if (state === 'ENDED') {
    hideCountdown();
    simTime = 0.0;
    scrubber.value = '0';
    renderAt(0);
    state = 'PLAYING';
    setToggleIcon('pause');
  }
